#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '../web/public/js/studio');
const order = ['01-state.js', '02-autopilot.js', '03-socket.js', '04-devices.js', '05-archive.js', '06-canvas.js', '07-overlays-draw.js', '08-overlays-ui.js', '09-whip.js', '10-color-picker.js', '11-windows.js', '12-startup-recording.js'];
let out = '/* AUTO-GENERATED by scripts/bundle-studio.js — edit files in web/public/js/studio/ then re-run */\n';
for (const f of order) {
  out += fs.readFileSync(path.join(dir, f), 'utf8');
  if (!out.endsWith('\n')) out += '\n';
}
const dest = path.join(__dirname, '../web/public/js/studio.js');
fs.writeFileSync(dest, out);
console.log('Wrote', dest, out.split(/\n/).length, 'lines');
